az group create \

  --name rg-dev-portal-prod \
  --location eastus

# 2. Deploy Azure App Service for Portal
az appservice plan create \

  --name plan-dev-portal \
  --resource-group rg-dev-portal-prod \
  --sku P1V2 \
  --is-linux

az webapp create \

  --name app-dev-portal-prod \
  --resource-group rg-dev-portal-prod \
  --plan plan-dev-portal \
  --runtime "NODE|18-lts"

# 3. Configure Custom Domain
az webapp config hostname add \

  --resource-group rg-dev-portal-prod \
  --webapp-name app-dev-portal-prod \
  --hostname developer.gainwell.com

# 4. Deploy PostgreSQL Database
az postgres flexible-server create \

  --name postgres-dev-portal-prod \
  --resource-group rg-dev-portal-prod \
  --location eastus \
  --admin-user portaladmin \
  --admin-password <secure-password> \
  --sku-name Standard_D2s_v3 \
  --tier GeneralPurpose \
  --version 13

# 5. Create database
