import React, { useEffect, useState } from 'react';
import { Grid, Card, CardContent, Typography, Chip } from '@mui/material';
import { apiService } from '../../services/apiService';

interface API {
  id: string;
  name: string;
  description: string;
  version: string;
  tags: string[];
  status: 'beta' | 'stable' | 'deprecated';
}

export const APIList: React.FC = () => {
  const [apis, setAPIs] = useState<API[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchAPIs = async () => {
      try {
        const data = await apiService.listAPIs();
        setAPIs(data);
      } catch (error) {
        console.error('Failed to load APIs:', error);
      } finally {
        setLoading(false);
      }
    };
    fetchAPIs();
  }, []);

  if (loading) return <div>Loading APIs...</div>;

  return (
    <Grid container spacing={3}>
      {apis.map(api => (
        <Grid item xs={12} sm={6} md={4} key={api.id}>
          <Card>
            <CardContent>
              <Typography variant="h6">{api.name}</Typography>
              <Typography variant="body2" color="textSecondary">
                {api.description}
              </Typography>
              <div style={{ marginTop: '10px' }}>
                <Chip label={api.version} size="small" />
                <Chip
                  label={api.status}
                  size="small"
                  color={api.status === 'stable' ? 'success' : 'default'}
                  style={{ marginLeft: '5px' }}
                />
              </div>
            </CardContent>
          </Card>
        </Grid>
      ))}
    </Grid>
  );
};
```

