// Example: API Key Generation Service
// src/services/keyManagementService.js
const crypto = require('crypto');
const { APIKey } = require('../models');
const gatewayService = require('./apiGatewayService');

class KeyManagementService {
  // Generate cryptographically secure API key
  generateKey() {
    return 'gwl_' + crypto.randomBytes(32).toString('hex');
  }

  // Create sandbox API key (instant provisioning)
  async createSandboxKey(developerId, apiId) {
    const key = this.generateKey();
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 30); // 30-day expiration

    // Store in database
    const apiKey = await APIKey.create({
      key: key,
      developerId: developerId,
      apiId: apiId,
      environment: 'sandbox',
      status: 'active',
      rateLimit: 1000, // 1000 req/hour default
      expiresAt: expiresAt
    });

    // Configure in API Gateway
    await gatewayService.createSubscription({
      key: key,
      developerId: developerId,
      apiId: apiId,
      environment: 'sandbox',
      rateLimit: 1000
    });

    return {
      keyId: apiKey.id,
      key: key,
      environment: 'sandbox',
      rateLimit: 1000,
      expiresAt: expiresAt
    };
  }

  // Request production API key (requires approval workflow)
  async requestProductionKey(developerId, apiId, justification) {
    // Create pending key request
    const request = await APIKey.create({
      developerId: developerId,
      apiId: apiId,
      environment: 'production',
      status: 'pending_approval',
      justification: justification
    });

    // Trigger approval workflow (Azure Logic App, email, etc.)
    await this.triggerApprovalWorkflow(request);

    return {
      requestId: request.id,
      status: 'pending_approval',
      message: 'Production access request submitted for review'
    };
  }
}

module.exports = new KeyManagementService();
```

**Week 7-8: API Gateway Integration**
```javascript
// src/services/apiGatewayService.js
// Integration with Azure APIM

const axios = require('axios');

class APIGatewayService {
  constructor() {
    this.apimBaseUrl = process.env.APIM_BASE_URL;
    this.apimApiKey = process.env.APIM_API_KEY;
  }

  // List all APIs from Azure APIM
  async listAPIs() {
    const response = await axios.get(
      `${this.apimBaseUrl}/subscriptions/${process.env.AZURE_SUBSCRIPTION_ID}/resourceGroups/${process.env.RESOURCE_GROUP}/providers/Microsoft.ApiManagement/service/${process.env.APIM_SERVICE_NAME}/apis`,
      {
        headers: {
          'Authorization': `Bearer ${this.apimApiKey}`,
          'Content-Type': 'application/json'
        },
        params: {
          'api-version': '2021-08-01'
        }
      }
    );

    return response.data.value.map(api => ({
      id: api.name,
      name: api.properties.displayName,
      description: api.properties.description,
      version: api.properties.apiVersion,
      path: api.properties.path,
      protocols: api.properties.protocols,
      subscriptionRequired: api.properties.subscriptionRequired
    }));
  }

  // Get OpenAPI specification for an API
  async getAPISpec(apiId) {
    const response = await axios.get(
      `${this.apimBaseUrl}/subscriptions/${process.env.AZURE_SUBSCRIPTION_ID}/resourceGroups/${process.env.RESOURCE_GROUP}/providers/Microsoft.ApiManagement/service/${process.env.APIM_SERVICE_NAME}/apis/${apiId}`,
      {
        headers: {
          'Authorization': `Bearer ${this.apimApiKey}`,
          'Content-Type': 'application/json'
        },
        params: {
          'api-version': '2021-08-01',
          'export': 'true',
          'format': 'openapi+json-link'
        }
      }
    );

    return response.data; // Returns OpenAPI 3.0 spec
  }

  // Create API subscription (API key provisioning)
  async createSubscription(options) {
    const { key, developerId, apiId, environment, rateLimit } = options;

    const response = await axios.put(
      `${this.apimBaseUrl}/subscriptions/${process.env.AZURE_SUBSCRIPTION_ID}/resourceGroups/${process.env.RESOURCE_GROUP}/providers/Microsoft.ApiManagement/service/${process.env.APIM_SERVICE_NAME}/subscriptions/sub-${developerId}-${apiId}`,
      {
        properties: {
          scope: `/apis/${apiId}`,
          displayName: `${developerId} - ${apiId} (${environment})`,
          state: 'active',
          allowTracing: environment === 'sandbox',
          primaryKey: key
        }
      },
      {
        headers: {
          'Authorization': `Bearer ${this.apimApiKey}`,
          'Content-Type': 'application/json'
        },
        params: {
          'api-version': '2021-08-01'
        }
      }
    );

    return response.data;
  }
}

module.exports = new APIGatewayService();
```

**Week 9-10: Authentication Integration**
```javascript
// src/services/authService.ts (Frontend)
import { PublicClientApplication } from '@azure/msal-browser';

const msalConfig = {
  auth: {
    clientId: process.env.REACT_APP_AZURE_CLIENT_ID!,
    authority: `https://${process.env.REACT_APP_B2C_TENANT}.b2clogin.com/${process.env.REACT_APP_B2C_TENANT}.onmicrosoft.com/${process.env.REACT_APP_SIGNUP_SIGNIN_POLICY}`,
    knownAuthorities: [`${process.env.REACT_APP_B2C_TENANT}.b2clogin.com`],
    redirectUri: window.location.origin
  },
  cache: {
    cacheLocation: 'sessionStorage',
    storeAuthStateInCookie: false
  }
};

export const msalInstance = new PublicClientApplication(msalConfig);

export const loginRequest = {
  scopes: ['openid', 'profile', 'email']
};

export class AuthService {
  async login() {
    try {
      const response = await msalInstance.loginPopup(loginRequest);
      return response.account;
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    }
  }

  async logout() {
    await msalInstance.logoutPopup();
  }

  async getAccessToken() {
    const accounts = msalInstance.getAllAccounts();
    if (accounts.length === 0) return null;

    const request = {
      scopes: [process.env.REACT_APP_API_SCOPE!],
      account: accounts[0]
    };

    try {
      const response = await msalInstance.acquireTokenSilent(request);
      return response.accessToken;
    } catch (error) {
      // Token expired, acquire new token interactively
