**Month 4: Production Access Workflows**
```javascript
// Implement approval workflow using Azure Logic Apps or custom state machine

// src/services/workflowService.js
const { ServiceBusClient} = require('@azure/service-bus');

class WorkflowService {
  constructor() {
    this.serviceBusClient = new ServiceBusClient(process.env.SERVICE_BUS_CONNECTION_STRING);
    this.sender = this.serviceBusClient.createSender('production-access-requests');
  }

  async submitProductionAccessRequest(request) {
    const {
      developerId,
      apiId,
      justification,
      expectedVolume,
      useCase,
      requiresPHI
    } = request;

    // Determine approval workflow based on request characteristics
    const workflowType = this.determineWorkflowType(request);

    // Create workflow message
    const message = {
      body: {
        requestId: crypto.randomUUID(),
        developerId,
        apiId,
        justification,
        expectedVolume,
        useCase,
        requiresPHI,
        workflowType,
        status: 'pending',
        submittedAt: new Date().toISOString()
      }
    };

    // Send to Service Bus for async processing
    await this.sender.sendMessages(message);

    // Store request in database
    const accessRequest = await AccessRequest.create({
      ...message.body,
      status: 'pending_security_review'
    });

    // Send notification to approvers
    await this.notifyApprovers(accessRequest, workflowType);

    return accessRequest;
  }

  determineWorkflowType(request) {
    if (request.requiresPHI) {
      return 'phi-access'; // Requires BAA + security review + business approval
    } else if (request.expectedVolume > 10000) {
      return 'high-volume'; // Requires capacity planning review
    } else {
      return 'standard'; // Standard approval (1-2 days)
    }
  }

  async notifyApprovers(request, workflowType) {
    const approvers = await this.getApprovers(workflowType);

    for (const approver of approvers) {
      await emailService.send({
        to: approver.email,
        subject: `Production API Access Request - ${request.apiId}`,
        template: 'access-request-notification',
        data: {
          requestId: request.requestId,
          developerName: request.developerName,
          apiName: request.apiName,
          justification: request.justification,
          approvalUrl: `https://developer.gainwell.com/admin/approvals/${request.requestId}`
        }
      });
    }
  }
}
