#### Technical Safeguards (§164.312)

**Access Control (§164.312(a)(1))**
```javascript
// Role-Based Access Control Implementation
// src/middleware/rbac.js

const roles = {
  DEVELOPER: {
    permissions: [
      'api:read',
      'api:test',
      'key:create:sandbox',
      'key:view:own',
      'analytics:view:own'
    ]
  },
  PARTNER_DEVELOPER: {
    permissions: [
      'api:read',
      'api:test',
      'key:create:sandbox',
      'key:request:production',
      'key:view:own',
      'analytics:view:own',
      'support:create:ticket'
    ]
  },
  API_TEAM: {
    permissions: [
      'api:read',
      'api:create',
      'api:update',
      'key:approve:production',
      'analytics:view:all',
      'developer:view:all'
    ]
  },
  PORTAL_ADMIN: {
    permissions: ['*'] // Full access
  }
};

function requirePermission(permission) {
  return async (req, res, next) => {
    const userRole = req.user.role;
    const userPermissions = roles[userRole].permissions;

    if (userPermissions.includes('*') || userPermissions.includes(permission)) {
      next();
    } else {
      // Log unauthorized access attempt (HIPAA audit requirement)
      await auditLogger.log({
        event: 'unauthorized_access_attempt',
        userId: req.user.id,
        requestedPermission: permission,
        timestamp: new Date().toISOString(),
        ipAddress: req.ip
      });

      return res.status(403).json({
        error: 'insufficient_permissions',
        message: 'You do not have permission to perform this action'
      });
    }
  };
}

// Usage in routes
app.post('/api/keys/production',
  requirePermission('key:approve:production'),
  async (req, res) => {
    // Handle production key approval
  }
);
```

**Audit Controls (§164.312(b))**
```javascript
// Comprehensive Audit Logging
// src/middleware/auditLogger.js

const { ApplicationInsights } = require('@azure/monitor-opentelemetry-exporter');

class AuditLogger {
  constructor() {
    this.client = new ApplicationInsights({
      connectionString: process.env.APPINSIGHTS_CONNECTION_STRING
    });
  }

  async log(event) {
    const auditEntry = {
      timestamp: new Date().toISOString(),
      eventType: event.type,
      userId: event.userId,
      userEmail: event.userEmail,
      action: event.action,
      resource: event.resource,
      resourceId: event.resourceId,
      result: event.result, // success, failure, denied
      ipAddress: event.ipAddress,
      userAgent: event.userAgent,
      details: event.details
    };

    // Send to Azure Log Analytics (HIPAA audit log retention: 6 years)
    this.client.trackEvent({
      name: 'AuditEvent',
      properties: auditEntry
    });

    // Also store in database for fast queries
    await AuditLog.create(auditEntry);

    // If critical event, send alert
    if (this.isCriticalEvent(event)) {
      await this.sendSecurityAlert(auditEntry);
    }
  }

  isCriticalEvent(event) {
    const criticalEvents = [
      'unauthorized_access_attempt',
      'api_key_leakage_detected',
      'bulk_data_download',
      'admin_privilege_escalation',
      'production_key_revocation'
    ];
    return criticalEvents.includes(event.type);
  }
}

// Log all API requests
app.use((req, res, next) => {
  const originalSend = res.send;
  res.send = function(data) {
    auditLogger.log({
      type: 'api_request',
      userId: req.user?.id,
      userEmail: req.user?.email,
      action: `${req.method} ${req.path}`,
      resource: req.path,
      result: res.statusCode < 400 ? 'success' : 'failure',
      ipAddress: req.ip,
      userAgent: req.get('User-Agent')
    });
    originalSend.call(this, data);
  };
  next();
});
```

**Integrity Controls (§164.312(c)(1))**
- API key generation uses cryptographically secure random number generator
- Database integrity constraints prevent invalid data states
- Checksums verified for uploaded OpenAPI specifications

**Transmission Security (§164.312(e)(1))**
- TLS 1.3 required for all portal connections
- Certificate pinning for mobile app connections (if applicable)
- No plain HTTP connections allowed (automatic redirect to HTTPS)

